// Main Prismatic Body
module main_prismatic_body() {
  cube([L, W, H], center=true);
}

// Side Cutouts
module side_cutout_left() {
  translate([0, -(W/2) + (cutout_depth + overlap)/2, 0])
    cube([cutout_length, cutout_depth + overlap, cutout_height], center=true);
}

