module hole_pattern() {
  for (x = [-hole_pitch_x/2, hole_pitch_x/2])
    for (y = [-hole_pitch_y/2, 0, hole_pitch_y/2])
      translate([-L/2 + hole_grid_center_x + x, hole_grid_center_y + y, 0])
        cylinder(r=hole_d/2, h=T + 2*overlap, center=true);
