// Operations
module plate() {
  difference() {
    union() {
      union() {
        union() {
          union() {
            main_rect_core();
            main_left_round();
            main_right_round();
          }
          step_shoulder();
        }
        extension();
      }
      difference() {
        union() {
          notch_rect_cut();
          notch_round_cut();
        }
      }
    }
    hole_pattern();
    small_hole();
    counterbores();
    lightening_pocket();
  }
}

// Final output
