module edge_soften() {
    cham = 0.35;
    difference() {
        children();

        // Remove tiny wedges along the two long top edges
        for (sy = [-1, 1]) {
            translate([0, sy*(W/2 - cham/2), H/2 - cham/2])
                rotate([0, 45*sy, 0])  // slight bevel feel without changing overall size much
                    cube([L + 2*overlap, cham, cham], center=true);
        }
    }
}

module final_model() {
    edge_soften()
        strip_solid();
}

