        [-(outer_hex_flat_to_flat_Y - 2*edge_chamfer)/(2*sqrt(3)), -(outer_hex_flat_to_flat_Y - 2*edge_chamfer)/2],
        [(outer_hex_flat_to_flat_Y - 2*edge_chamfer)/(2*sqrt(3)), -(outer_hex_flat_to_flat_Y - 2*edge_chamfer)/2]
      ]);
}

// Edge Fillet Kernel
