// Hex prismatic spacer/fixture block with:
// - flat-to-flat hex body (W) and controlled overall length (L) via clipping
// - single small circular through-hole near center
// - diagonal recessed band/groove on the top face
// - slight end steps/chamfers (top face) near both ends
// - small notch-like relief on one end
// Bounding box target: 46.2 x 40.0 x 7.0 mm

$fn = 128;

// Target bounding box
L = 46.2;     // X
W = 40.0;     // Y (flat-to-flat)
H = 7.0;      // Z

eps = 0.05;

// Hex geometry (flat-to-flat = W)
apothem = W/2;
R = apothem / cos(30);   // circumradius

// Features
hole_d = 4.0;

groove_w = 6.0;
groove_depth = 1.0;
groove_angle = 30;       // degrees
groove_y_offset = 0.0;

step_len = 3.0;          // length of end step region (each end)
step_inset = 1.0;        // in-plane inset for step
step_drop = 0.5;         // depth of step from top face

notch_w = 6.0;           // along Y
notch_d = 3.0;           // into part from end (along X)
notch_z = H;             // through thickness

// 2D regular hex with flats horizontal (flat-to-flat = W)
module hex2d(ap) {
    RR = ap / cos(30);
    polygon(points=[
        [ RR, 0],
        [ RR/2,  RR*sqrt(3)/2],
        [-RR/2,  RR*sqrt(3)/2],
        [-RR, 0],
        [-RR/2, -RR*sqrt(3)/2],
        [ RR/2, -RR*sqrt(3)/2]
    ]);
}

// Base hex prism, clipped to exact length L in X
module clipped_hex_prism(h) {
    intersection() {
        linear_extrude(height=h, center=true)
            hex2d(apothem);
        cube([L, 2*R + 2*eps, h + 2*eps], center=true);
    }
}

// End top steps (shallow recessed pads) to suggest chamfer/step at ends
module end_top_steps() {
    zc = H/2 - step_drop/2 + eps/2;
    for (sx = [-1, 1]) {
        translate([sx*(L/2 - step_len/2), 0, zc])
            intersection() {
                // limit to end region
                cube([step_len + 2*eps, 2*R + 2*eps, step_drop + eps], center=true);
                // inset hex footprint
                linear_extrude(height=step_drop + eps, center=true)
                    hex2d(max(0.01, apothem - step_inset));
            }
    }
}

// Main solid body (one connected solid)
module body() {
    union() {
        clipped_hex_prism(H);
        end_top_steps();
    }
}

// Through-hole
module through_hole() {
    cylinder(d=hole_d, h=H + 4*eps, center=true);
}

// Diagonal recessed groove on top face
module top_groove() {
    zc = H/2 - groove_depth/2 + eps/2;
    translate([0, groove_y_offset, zc])
        rotate([0, 0, groove_angle])
            cube([L + 4*eps, groove_w, groove_depth + 2*eps], center=true);
}

// Notch-like relief on +X end
module end_notch() {
    x0 = L/2 - notch_d/2 + eps/2; // ensure it bites into the end
    translate([x0, 0, 0])
        cube([notch_d + 2*eps, notch_w, notch_z + 4*eps], center=true);
}

// Final model
difference() {
    body();
    through_hole();
    top_groove();
    end_notch();
}

// Fixed OpenSCAD model: thick hex plate with visible through-hole,
// clear perimeter steps/notches, and asymmetric top/bottom reliefs.
// Ensures ONE connected solid and non-blank render by using consistent centering.

// ---------- Parameters ----------
bbox_x = 46.19;                 // target overall X (approx, via hex corners)
bbox_y = 40.0;                  // target overall Y (flat-to-flat)
thickness_z = 19.0;             // overall thickness

hex_flat_to_flat = 40.0;        // across flats (Y direction when point-up)
hex_rotation_deg = 0.0;

hole_d = 6.0;
hole_offset_x = 1.5;
hole_offset_y = -0.8;

notch_count = 6;
notch_w = 6.0;                  // tangential width
notch_d = 2.0;                  // radial depth into perimeter
notch_h = 4.0;                  // vertical height of notch cut
notch_z_from_top = 0.0;         // 0 => starts at top surface

top_relief_1_w = 18.0;
top_relief_1_d = 8.0;
top_relief_1_depth = 3.0;
top_relief_1_offset_x = 6.0;
top_relief_1_offset_y = 0.0;

top_relief_2_w = 10.0;
top_relief_2_d = 6.0;
top_relief_2_depth = 2.0;
top_relief_2_offset_x = -8.0;
top_relief_2_offset_y = 6.0;

bottom_relief_1_w = 16.0;
bottom_relief_1_d = 10.0;
bottom_relief_1_depth = 3.0;
bottom_relief_1_offset_x = -5.0;
bottom_relief_1_offset_y = -4.0;

bottom_relief_2_w = 9.0;
bottom_relief_2_d = 7.0;
bottom_relief_2_depth = 2.0;
bottom_relief_2_offset_x = 7.0;
bottom_relief_2_offset_y = -7.0;

edge_chamfer_size = 0.8;        // small corner reliefs (optional)
alignment_mark_d = 2.0;
alignment_mark_depth = 0.6;
alignment_mark_offset_r = 14.0;

overlap = 1.0;

countersink_enable = 0;
countersink_top_d = 10.0;
countersink_depth = 3.0;

// ---------- Derived ----------
hex_apothem = hex_flat_to_flat/2;                 // center to flat
hex_corner_r = hex_flat_to_flat/sqrt(3);          // center to corner (circumradius)

// ---------- Helpers ----------
module hex_prism(ftf, h, rot=0) {
    // Use cylinder with $fn=6 for robust, centered hex prism.
    // For a regular hex: across flats = sqrt(3)*R => R = ftf/sqrt(3)
    rotate([0,0,rot])
        cylinder(h=h, r=ftf/sqrt(3), $fn=6, center=true);
}

module through_hole() {
    translate([hole_offset_x, hole_offset_y, 0])
        cylinder(h=thickness_z + 2*overlap, r=hole_d/2, center=true, $fn=64);
}

module perimeter_notch(angle_deg) {
    // Cut a shallow rectangular step into each flat, near the perimeter.
    // Place the notch so its outer face slightly exceeds the flat plane to guarantee intersection.
    // Flat plane is at radius = hex_apothem.
    rotate([0,0,angle_deg])
        translate([hex_apothem - notch_d/2 + overlap/2, 0,
                   thickness_z/2 - notch_z_from_top - notch_h/2])
            cube([notch_d + overlap, notch_w, notch_h + overlap], center=true);
}

module top_relief(w,d,depth,ox,oy) {
    translate([ox, oy, thickness_z/2 - depth/2])
        cube([w, d, depth + overlap], center=true);
}

module bottom_relief(w,d,depth,ox,oy) {
    translate([ox, oy, -thickness_z/2 + depth/2])
        cube([w, d, depth + overlap], center=true);
}

module edge_corner_relief(angle_deg) {
    // Small corner reliefs near vertices to suggest chamfer/relief without complex minkowski.
    rotate([0,0,angle_deg])
        translate([hex_corner_r - edge_chamfer_size/2 + overlap/2, 0, 0])
            cube([edge_chamfer_size + overlap, edge_chamfer_size + overlap, thickness_z + 2*overlap], center=true);
}

module alignment_mark(angle_deg) {
    rotate([0,0,angle_deg])
        translate([alignment_mark_offset_r, 0, thickness_z/2 - alignment_mark_depth/2])
            cylinder(r=alignment_mark_d/2, h=alignment_mark_depth + overlap, center=true, $fn=48);
}

module countersink_variant() {
    if (countersink_enable) {
        translate([hole_offset_x, hole_offset_y, thickness_z/2 - countersink_depth/2])
            cylinder(r1=countersink_top_d/2, r2=hole_d/2, h=countersink_depth + overlap, center=true, $fn=64);
    }
}

// ---------- Complete Model ----------
module complete_model() {
    difference() {
        // Main body centered at origin to match all subtractive features
        hex_prism(hex_flat_to_flat, thickness_z, hex_rotation_deg);

        union() {
            // Central through-hole (now correctly centered in Z and guaranteed to cut through)
            through_hole();

            // Perimeter notches/steps around flats
            for (i = [0:notch_count-1])
                perimeter_notch(i * 360/notch_count);

            // Asymmetric top reliefs (cuts)
            top_relief(top_relief_1_w, top_relief_1_d, top_relief_1_depth, top_relief_1_offset_x, top_relief_1_offset_y);
            top_relief(top_relief_2_w, top_relief_2_d, top_relief_2_depth, top_relief_2_offset_x, top_relief_2_offset_y);

            // Asymmetric bottom reliefs (different from top)
            bottom_relief(bottom_relief_1_w, bottom_relief_1_d, bottom_relief_1_depth, bottom_relief_1_offset_x, bottom_relief_1_offset_y);
            bottom_relief(bottom_relief_2_w, bottom_relief_2_d, bottom_relief_2_depth, bottom_relief_2_offset_x, bottom_relief_2_offset_y);

            // Small corner reliefs at vertices (optional but helps stepped/keyed look)
            for (i = [0:5])
                edge_corner_relief(i * 60 + 30); // vertices for point-up hex

            // Small alignment marks on top face
            alignment_mark(0);
            alignment_mark(210);

            // Optional countersink
            countersink_variant();
        }
    }
}

complete_model();

$fn = 96;

// Parameters (mm)
bbox_L = 46.19;                 // overall across flats (X)
bbox_W = 40.0;                  // overall across corners (Y) for pointy-top orientation
T = 7.0;                        // thickness (Z)

hole_d = 10.0;
hole_offset_x = 0.0;
hole_offset_y = 0.0;

groove_depth = 0.8;             // recess depth into face
groove_angle_deg = 60.0;        // included angle of V (in face plane)
groove_land_w = 2.0;            // small flat land at the chevron meeting line
groove_span_w = 28.0;           // span along Z (height on the face)
groove_span_h = 14.0;           // span along Y (width on the face)
overlap = 1.0;                  // boolean robustness

// --- Helpers ---
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Regular hex in XY with flat-to-flat = bbox_L (pointy-top orientation gives corner-to-corner = bbox_W)
module hex_prism_body() {
    // For a regular hex: across flats = sqrt(3)*R, across corners = 2*R
    // Choose R from bbox_L, and scale Y slightly to match bbox_W exactly.
    R = bbox_L / sqrt(3);
    yscale = bbox_W / (2*R);

    linear_extrude(height=T, center=true, convexity=10)
        scale([1, yscale])
            circle(r=R, $fn=6);
}

module through_hole() {
    translate([hole_offset_x, hole_offset_y, 0])
        cylinder(d=hole_d, h=T + 2*overlap, center=true);
}

// V/chevron recess cut into the +X face, spanning Y and Z.
// Implemented as intersection of two half-spaces (forming a V) extruded along X.
module chevron_cut_on_posX() {
    // Keep groove within the face extents
    spanY = clamp(groove_span_h, groove_land_w + 0.2, bbox_W - 2);
    spanZ = clamp(groove_span_w, 1, T - 0.2);

    // Place the cutter so it starts at the +X face and goes inward by groove_depth
    // Body max X is bbox_L/2 (across flats)
    x_face = bbox_L/2;
    x_center = x_face - groove_depth/2 + overlap/2;

    // V geometry in the YZ plane:
    // Two planes: |y| <= land/2 + z*tan(theta/2), with z measured from the face midline.
    theta = groove_angle_deg;
    tanh = tan(theta/2);

    translate([x_center, 0, 0])
    rotate([0, 90, 0])  // extrude along X by linear_extrude in local Z
    linear_extrude(height=groove_depth + overlap, center=true, convexity=10)
        intersection() {
            // Limit to a rectangle window on the face
            square([spanY, spanZ], center=true);

            // Intersect the two half-planes to form the V (chevron) with a flat land
            // Use a big bounding square and clip with polygons representing the half-planes.
            // Condition: y <= land/2 + z*tanh  and  y >= -land/2 - z*tanh
            // Achieved by intersecting two large polygons.
            union() {
                // Upper bound polygon for y <= land/2 + z*tanh
                polygon(points=[
                    [-1e3, -1e3],
                    [ 1e3, -1e3],
                    [ 1e3,  (groove_land_w/2) + 1e3*tanh],
                    [-1e3,  (groove_land_w/2) - 1e3*tanh]
                ]);

                // Lower bound polygon for y >= -land/2 - z*tanh  (i.e., -y <= land/2 + z*tanh)
                // Equivalent to y >= -land/2 - z*tanh
                polygon(points=[
                    [-1e3, (-groove_land_w/2) - 1e3*tanh],
                    [ 1e3, (-groove_land_w/2) + 1e3*tanh],
                    [ 1e3,  1e3],
                    [-1e3,  1e3]
                ]);
            }
        }
}

// Same chevron on the -X face (opposing face)
module chevron_cut_on_negX() {
    mirror([1,0,0]) chevron_cut_on_posX();
}

// Final Model
module final_model() {
    difference() {
        hex_prism_body();
        through_hole();
        chevron_cut_on_posX();
        chevron_cut_on_negX();
    }
}

color("Silver") final_model();

