// Helpers
module rounded_rect_2d(L, W, R) {
    // Robust rounded rectangle in 2D
    R2 = min(R, min(L, W)/2);
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx*(L/2 - R2), sy*(W/2 - R2)])
                circle(r=R2);
    }
}

module plate_solid() {
    linear_extrude(height=plate_T, center=true)
        rounded_rect_2d(plate_L, plate_W, corner_R);
}

