    translate([xc, win_y_offset, 0])
        cube([win_W, win_H, plate_T + 2*cut_through_extra], center=true);
}

module hole_cutout(x, y, d) {
    translate([x, y, 0])
        cylinder(d=d, h=plate_T + 2*cut_through_extra, center=true);
}

