module capsule2d(len, r1, r2) {
    // 2D capsule/teardrop-like shape along +X, with different end radii
    // End centers at x=0 and x=len
    hull() {
        translate([0, 0]) circle(r=r1);
        translate([len, 0]) circle(r=r2);
    }
