// Render-safe stepped sleeve/connector (rotationally symmetric)
$fn = 48;

// Target bounding box (approx): 12.0 x 27.2 x 27.2 mm (elongated along Z)
L = 12.0;                 // overall length (Z)
D_max = 27.2;             // maximum OD (ribs)
D_mid = 24.8;             // main body OD
D_neck = 22.6;            // neck OD (between collars and mid)
D_end_collar = 26.2;      // end collar OD

L_end_collar = 1.2;       // each end collar axial length
L_mid_section = 6.6;      // central section axial length
overlap = 0.10;           // small overlap to guarantee connectivity

// Two prominent recessed bands near midsection (grooves)
band_w = 1.25;
band_gap = 1.10;
band_depth_rad = 1.10;

// Small end relief grooves
end_relief_w = 0.65;
end_relief_depth_rad = 0.65;

// Raised ribs (circumferential rings) near ends of mid section
rib_count = 6;
rib_w = 0.55;
rib_h_rad = 0.55;

// Edge chamfer (simple conical cut)
chamfer_ax = 0.55;

// Derived lengths
L_neck_total = max(0, L - L_mid_section - 2*L_end_collar);
L_neck_each  = L_neck_total/2;

// Axial landmarks (centered at Z=0)
z_left_end        = -L/2;
z_right_end       =  L/2;

z_left_collar_c   = z_left_end  + L_end_collar/2;
z_right_collar_c  = z_right_end - L_end_collar/2;

z_left_neck_c     = z_left_end  + L_end_collar + L_neck_each/2;
z_right_neck_c    = z_right_end - L_end_collar - L_neck_each/2;

module outer_profile_union() {
    union() {
        // Mid section (main body)
        cylinder(r=D_mid/2, h=L_mid_section + 2*overlap, center=true);

        // Necks
        if (L_neck_each > 0) {
            translate([0,0,z_left_neck_c])
                cylinder(r=D_neck/2, h=L_neck_each + 2*overlap, center=true);
            translate([0,0,z_right_neck_c])
                cylinder(r=D_neck/2, h=L_neck_each + 2*overlap, center=true);
        }

        // End collars
        translate([0,0,z_left_collar_c])
            cylinder(r=D_end_collar/2, h=L_end_collar + 2*overlap, center=true);

        translate([0,0,z_right_collar_c])
            cylinder(r=D_end_collar/2, h=L_end_collar + 2*overlap, center=true);
    }
}

module raised_ribs() {
    if (rib_count <= 0) { /* no ribs */ }
    else {
        margin = 0.25;
        z_min = -L_mid_section/2 + margin + rib_w/2;
        z_max =  L_mid_section/2 - margin - rib_w/2;

        // Groove centers
        z_g1 = -(band_gap/2 + band_w/2);
        z_g2 =  (band_gap/2 + band_w/2);

        // Exclusion half-span around each groove
        excl = band_w/2 + 0.20;

        for (i = [0:rib_count-1]) {
            t = (rib_count==1) ? 0.5 : i/(rib_count-1);
            zi = z_min + t*(z_max - z_min);

            ok = (abs(zi - z_g1) > (excl + rib_w/2)) && (abs(zi - z_g2) > (excl + rib_w/2));
            if (ok)
                translate([0,0,zi])
                    cylinder(r=min(D_max/2, D_mid/2 + rib_h_rad),
                             h=rib_w + 2*overlap, center=true);
        }
    }
}

module recessed_mid_bands_cuts() {
    z1 = -(band_gap/2 + band_w/2);
    z2 =  (band_gap/2 + band_w/2);

    // Cut rings: subtract only the outer annulus (avoid coplanar/degenerate booleans)
    for (zv = [z1, z2]) {
        translate([0,0,zv])
            difference() {
                cylinder(r=D_mid/2 + 0.02, h=band_w + 2*overlap, center=true);
                cylinder(r=max(0.01, D_mid/2 - band_depth_rad),
                         h=band_w + 2*overlap + 0.04, center=true);
            }
    }
}

module end_relief_grooves_cuts() {
    zL = z_left_end + L_end_collar + end_relief_w/2;
    zR = z_right_end - L_end_collar - end_relief_w/2;

    for (zv = [zL, zR]) {
        translate([0,0,zv])
            difference() {
                cylinder(r=D_neck/2 + 0.02, h=end_relief_w + 2*overlap, center=true);
                cylinder(r=max(0.01, D_neck/2 - end_relief_depth_rad),
                         h=end_relief_w + 2*overlap + 0.04, center=true);
            }
    }
}

module end_chamfer_cuts() {
    // Slightly oversize radii to ensure clean subtraction
    translate([0,0,z_left_end + chamfer_ax/2])
        cylinder(r1=0.01, r2=D_end_collar/2 + 0.05, h=chamfer_ax + 2*overlap, center=true);

    translate([0,0,z_right_end - chamfer_ax/2])
        cylinder(r1=D_end_collar/2 + 0.05, r2=0.01, h=chamfer_ax + 2*overlap, center=true);
}

module solid_connector() {
    difference() {
        union() {
            outer_profile_union();
            raised_ribs();
        }
        recessed_mid_bands_cuts();
        end_relief_grooves_cuts();
        end_chamfer_cuts();
    }
}

solid_connector();

// Rotationally symmetric spool-like turned sleeve/roller
// FIX: Replace frustum/cone-looking artifacts with a clean stepped cylindrical profile
// using a single continuous r-z polygon (rotate_extrude).
// Target bounding box: 23 x 23 x 24 mm (X x Y x Z), elongated along Z

$fn = 200;

// --- Parameters (mm) ---
L = 24;                 // overall length (Z)
D_max = 23;             // max OD (raised bands)
D_min = 12;             // min OD (grooves)
end_land_L = 4;         // raised end land length (each end)
groove_L = 3;           // recessed groove length (each groove)
band_L = 5;             // raised band length (between grooves)
fillet_r = 0.8;         // fillet radius at steps (r-z profile)
end_edge_r = 0.4;       // end edge rounding (r-z profile)

// --- Derived radii ---
R_max = D_max/2;
R_min = D_min/2;

// --- Axial layout (exactly fills L) ---
center_band_L = L - (2*end_land_L + 2*groove_L + band_L);
center_band_L = (center_band_L < 0) ? 0 : center_band_L;

z0 = -L/2;
z1 = z0 + end_land_L;
z2 = z1 + groove_L;
z3 = z2 + band_L;
z4 = z3 + groove_L;
z5 = z4 + center_band_L;
z6 = z0 + L;

// --- Helpers ---
function min3(a,b,c) = min(a, min(b,c));

// Rounded outer edge at left end: from (R-fe, z0) to (R, z0+fe)
function end_round_left(R, z0, fe, nsteps) =
    (fe <= 0) ? [] :
    [ for (i=[0:nsteps])
        let(t = i*90/nsteps)
        [ (R - fe) + fe*cos(t), z0 + fe*sin(t) ]
    ];

// Rounded outer edge at right end: from (R, z6-fe) to (R-fe, z6)
function end_round_right(R, z6, fe, nsteps) =
    (fe <= 0) ? [] :
    [ for (i=[0:nsteps])
        let(t = i*90/nsteps)
        [ R - fe*sin(t), (z6 - fe) + fe*cos(t) ]
    ];

module spool_profile() {
    // Clamp fillets so they fit within adjacent axial segments
    f1 = min3(fillet_r, end_land_L/2, groove_L/2);
    f2 = min3(fillet_r, groove_L/2, band_L/2);
    f3 = min3(fillet_r, band_L/2, groove_L/2);
    f4 = min3(fillet_r, groove_L/2, center_band_L/2);
    fe = min(end_edge_r, end_land_L/2);

    n  = 24;
    ne = max(10, floor(n/2));

    // Build ONE continuous, monotonic-in-z outer contour with explicit cylindrical steps.
    // Each shoulder uses a quarter-circle fillet that advances in z (no backwards arcs),
    // preventing self-intersections and "split/frustum" artifacts.

    pts = concat(
        // Start on axis at left end
        [[0, z0]],

        // Move to outer surface with end rounding
        [[R_max - fe, z0]],
        end_round_left(R_max, z0, fe, ne),

        // --- Segment A: left end land (R_max) ---
        [[R_max, z1 - f1]],

        // Fillet down: R_max -> R_min across z1..z1+f1
        [ for (i=[0:n])
            let(t = i*90/n)
            [ R_max - (R_max - R_min)*sin(t), (z1 - f1) + f1*(1 - cos(t)) ]
        ],

        // --- Segment B: groove 1 (R_min) ---
        [[R_min, z2 - f2]],

        // Fillet up: R_min -> R_max across z2..z2+f2
        [ for (i=[0:n])
            let(t = i*90/n)
            [ R_min + (R_max - R_min)*sin(t), (z2 - f2) + f2*(1 - cos(t)) ]
        ],

        // --- Segment C: raised band (R_max) ---
