// Blocky C-shaped bracket/frame with stepped outer perimeter and inner step transitions
// Target bounding box: 31.8 x 31.8 x 15.8 mm

$fn = 48;

// --- Parameters (mm) ---
outer_x = 31.8;
outer_y = 31.8;
thk     = 15.8;

// Main inner opening (rectangular)
inner_x = 18.0;
inner_y = 20.0;

// C-gap (opens to the bottom edge)
gap_w   = 8.0;

// Outer stepped perimeter (a shallow recess on the top face)
outer_step_depth = 2.0;     // inset from outer edges
outer_step_drop  = 1.2;     // depth of recess from top face

// Inner step transitions (small ledges around inner opening)
inner_step_w    = 1.2;
inner_step_len  = 10.0;
inner_step_drop = 0.8;      // depth of inner ledges from top face

// Boss pads (reinforced pads on top face)
boss_w = 6.0;
boss_l = 6.0;
boss_drop = 0.0;            // 0 => bosses are full thickness (flush); increase to make them top-only

// Robust boolean overlap
eps = 0.05;

// --- Helpers ---
module box_at(x, y, z, sx, sy, sz) {
    translate([x,y,z]) cube([sx,sy,sz], center=true);
}

// --- Core geometry ---
module base_plate() {
    cube([outer_x, outer_y, thk], center=true);
}

// Through openings to create the C-shape
module cut_inner_opening() {
    cube([inner_x, inner_y, thk + 2*eps], center=true);
}

module cut_bottom_gap() {
    // Ensure the gap actually reaches the outer bottom edge and intersects the inner opening.
    // Make it slightly wider in Y than the outer plate so it always cuts through.
    translate([0, -outer_y/2, 0])
        cube([gap_w, outer_y + 2*eps, thk + 2*eps], center=true);
}

// Top-face recess (outer perimeter step)
module cut_outer_top_recess() {
    recess_x = outer_x - 2*outer_step_depth;
    recess_y = outer_y - 2*outer_step_depth;
    recess_h = outer_step_drop;

    translate([0,0, thk/2 - recess_h/2 + eps])
        cube([recess_x, recess_y, recess_h + 2*eps], center=true);
}

// Inner step transitions (small top-face ledges around inner opening)
module cut_inner_step_transitions() {
    h = inner_step_drop;

    // Place these cuts so they nibble into the frame around the opening (not floating).
    // Keep them shallow and on the top face.
    zc = thk/2 - h/2 + eps;

    // Top ledge cut
    translate([0,  inner_y/2 + inner_step_w/2, zc])
        cube([inner_step_len, inner_step_w, h + 2*eps], center=true);

    // Bottom ledge cut (still fine; the C-gap is separate and will open the bottom)
    translate([0, -inner_y/2 - inner_step_w/2, zc])
        cube([inner_step_len, inner_step_w, h + 2*eps], center=true);

    // Left ledge cut
    translate([-inner_x/2 - inner_step_w/2, 0, zc])
        cube([inner_step_w, inner_step_len, h + 2*eps], center=true);

    // Right ledge cut
    translate([ inner_x/2 + inner_step_w/2, 0, zc])
        cube([inner_step_w, inner_step_len, h + 2*eps], center=true);
}

// Boss pads (add material; keep connected by overlapping with base)
module boss_pads() {
    boss_h = (boss_drop <= 0) ? thk : (thk - boss_drop);
    boss_z = (boss_drop <= 0) ? 0 : (boss_drop/2);

    // Corner bosses
    x0 = outer_x/2 - boss_w/2;
    y0 = outer_y/2 - boss_l/2;

    box_at(-x0,  y0, boss_z, boss_w, boss_l, boss_h);
    box_at(-x0, -y0, boss_z, boss_w, boss_l, boss_h);
    box_at( x0,  y0, boss_z, boss_w, boss_l, boss_h);
    box_at( x0, -y0, boss_z, boss_w, boss_l, boss_h);

    // Small mid bosses on left side (reinforced pads near the "legs")
    sm_w = boss_w*0.7;
    sm_l = boss_l*0.5;

    xl = -outer_x/2 + sm_w/2;
    yt =  outer_y/2 - sm_l/2;
    yb = -outer_y/2 + sm_l/2;

    box_at(xl, yt, boss_z, sm_w, sm_l, boss_h);
    box_at(xl, yb, boss_z, sm_w, sm_l, boss_h);
}

// --- Final model ---
module bracket() {
    difference() {
        union() {
            base_plate();
            boss_pads(); // additive, overlaps base => one connected solid
        }

        // Through cuts for C-shape
        cut_inner_opening();
        cut_bottom_gap();

        // Top-face stepped details
        cut_outer_top_recess();
        cut_inner_step_transitions();
    }
}

bracket();

// Stepped, asymmetric H-like bracket/block (prismatic, sharp edges)
// Target bounding box: 31.8 x 31.8 x 15.8 mm

$fn = 48;

// --- Parameters (mm) ---
bbox_x = 31.8;
bbox_y = 31.8;
bbox_z = 15.8;

// H core (two end blocks + central bridge)
end_block_x = 12.0;
end_block_y = bbox_y;
end_block_z = bbox_z;

bridge_x = bbox_x - 2*end_block_x;   // ensures exact bbox_x
bridge_y = 12.0;
bridge_z = bbox_z;

// Shoulder steps / rebates (cuts)
top_rebate_depth = 2.0;
top_rebate_y     = 18.0;
top_rebate_x     = bbox_x;

bottom_rebate_depth = 2.5;
bottom_rebate_y     = 14.0;
bottom_rebate_x     = 20.0;

// Asymmetric pads (additions) - made more pronounced
pad_top_x = 12.0;
pad_top_y = 9.0;
pad_top_z = 3.0;
pad_top_offset_x = 6.8;
pad_top_offset_y = 9.2;

pad_bottom_x = 9.5;
pad_bottom_y = 12.0;
pad_bottom_z = 3.5;
pad_bottom_offset_x = -8.2;
pad_bottom_offset_y = -7.6;

// Small lip on top (addition)
lip_x = 7.0;
lip_y = 4.5;
lip_z = 1.5;
lip_offset_x = 0.0;
lip_offset_y = -10.2;

// Corner relief notches (cuts)
notch_x = 3.0;
notch_y = 3.0;
notch_z = 4.0;

overlap = 0.25; // overlap to guarantee manifold unions/differences

// --- Core H solid (union of 3 prisms) ---
module h_core() {
  union() {
    // left end block
    translate([-(bbox_x/2 - end_block_x/2), 0, 0])
      cube([end_block_x, end_block_y, end_block_z], center=true);

    // right end block
    translate([(bbox_x/2 - end_block_x/2), 0, 0])
      cube([end_block_x, end_block_y, end_block_z], center=true);

    // central bridge (exactly spans between end blocks)
    cube([bridge_x, bridge_y, bridge_z], center=true);
  }
}

// --- Add asymmetric pads and lip (all connected) ---
module additions() {
  union() {
    // top offset pad (sits on top face, overlaps into body)
    translate([pad_top_offset_x, pad_top_offset_y,
               bbox_z/2 - pad_top_z/2 - overlap])
      cube([pad_top_x, pad_top_y, pad_top_z], center=true);

    // bottom offset pad (sits on bottom face, overlaps into body)
    translate([pad_bottom_offset_x, pad_bottom_offset_y,
               -(bbox_z/2 - pad_bottom_z/2 - overlap)])
      cube([pad_bottom_x, pad_bottom_y, pad_bottom_z], center=true);

    // small alignment lip protruding from top face, overlaps slightly
    translate([lip_offset_x, lip_offset_y,
               bbox_z/2 + lip_z/2 - overlap])
      cube([lip_x, lip_y, lip_z], center=true);
  }
}

// --- Shoulder steps/rebates (cuts) ---
module top_rebate_cut() {
  translate([0, 0, bbox_z/2 - top_rebate_depth/2 + overlap])
    cube([top_rebate_x + 2*overlap,
          top_rebate_y + 2*overlap,
          top_rebate_depth + 2*overlap], center=true);
}

module bottom_rebate_cut() {
  translate([0, 0, -(bbox_z/2 - bottom_rebate_depth/2 + overlap)])
    cube([bottom_rebate_x + 2*overlap,
          bottom_rebate_y + 2*overlap,
          bottom_rebate_depth + 2*overlap], center=true);
}

// --- Corner relief notches (cuts) ---
module corner_notches_cut() {
  for (sx = [-1, 1], sy = [-1, 1]) {
    translate([sx*(bbox_x/2 - notch_x/2),
               sy*(bbox_y/2 - notch_y/2),
               bbox_z/2 - notch_z/2 + overlap])
      cube([notch_x + 2*overlap,
            notch_y + 2*overlap,
            notch_z + 2*overlap], center=true);
  }
}

// --- Final model (ONE connected solid) ---
difference() {
  union() {
    h_core();
    additions();
  }
  top_rebate_cut();
  bottom_rebate_cut();
  corner_notches_cut();
}

// Symmetric double-ended wedge/clevis-like spacer with opposing flared arms
// and two opposing tapered triangular through-openings.
// Bounding box target: 54.5 x 22.2 x 29.5 mm (X x Y x Z)

$fn = 64;

// Overall bounds
L = 54.47;
W = 22.24;
H = 29.48;

// Central block (short)
block_L = 14.0;
block_W = W;
block_H = 16.0;

// Arms (each side)
arm_L_each = (L - block_L)/2;   // ensures exact overall length
arm_end_W  = W;
arm_end_H  = H;

// Waist (hourglass/X silhouette in side view)
waist_W = 12.5;
waist_H = 18.0;

// Triangular tunnel parameters (taper toward center)
tunnel_len_each = 22.0;         // from each end toward center
tri_entry_side  = 16.0;         // triangle size at the ends
tri_throat_side = 8.0;          // triangle size near the center

// Overlaps for robust booleans / solid connections
overlap = 1.2;

// Helpers
function tri_pts(side) =
    let(h = side*sqrt(3)/2)
    [ [0,  2*h/3],
      [-side/2, -h/3],
      [ side/2, -h/3] ];

module central_block() {
    cube([block_L, block_W, block_H], center=true);
}

// One arm as a polyhedron (local x from 0..arm_L_each), then mirrored for the other side.
// Cross-section in YZ is a rectangle that linearly scales from end (arm_end_*) to waist (*).
module arm_half_poly() {
    x0 = 0;
    x1 = arm_L_each;

    // End rectangle (at x0)
    y0 = arm_end_W/2;
    z0 = arm_end_H/2;

    // Waist rectangle (at x1)
    y1 = waist_W/2;
    z1 = waist_H/2;

    polyhedron(
        points=[
            // x0 end
            [x0, -y0, -z0], [x0,  y0, -z0], [x0,  y0,  z0], [x0, -y0,  z0],
            // x1 waist
            [x1, -y1, -z1], [x1,  y1, -z1], [x1,  y1,  z1], [x1, -y1,  z1]
        ],
        faces=[
            // end cap (x0)
            [0,1,2], [0,2,3],
            // waist cap (x1)
            [4,6,5], [4,7,6],
            // sides
            [0,4,5], [0,5,1],   // -Z face
            [1,5,6], [1,6,2],   // +Y face
            [2,6,7], [2,7,3],   // +Z face
            [3,7,4], [3,4,0]    // -Y face
        ],
        convexity=10
    );
}

module outer_body() {
    union() {
        central_block();

        // Place each arm so its WAIST face overlaps into the central block by `overlap`.
        // Left arm: local waist at x=arm_L_each should land at x = -block_L/2 + overlap
        left_arm_origin_x = (-block_L/2 + overlap) - arm_L_each;
        translate([left_arm_origin_x, 0, 0])
            arm_half_poly();

        // Right arm: mirror the left placement about X=0
        mirror([1,0,0])
            translate([left_arm_origin_x, 0, 0])
                arm_half_poly();
    }
}

// TRUE tapered triangular through-tunnel from one end toward the center.
// Implemented as a polyhedron "triangular pyramid frustum" aligned along X.
// This avoids orientation/axis mistakes and guarantees a clean through-cut.
module tapered_tri_tunnel_half(sign=1) {
    // sign = -1 for left end, +1 for right end
    // Start slightly outside the end face and extend inward.
    x0 = sign*(L/2 + overlap);
    x1 = sign*(L/2 - tunnel_len_each - overlap);

    // Triangle sizes
    s0 = tri_entry_side;
    s1 = tri_throat_side;

    // Triangle points in YZ plane (centered at Y=0,Z=0)
    // tri_pts() returns points around origin already.
    p0 = tri_pts(s0);
    p1 = tri_pts(s1);

    // Build polyhedron points: 0..2 at x0, 3..5 at x1
    polyhedron(
        points=[
            [x0, p0[0][0], p0[0][1]],
            [x0, p0[1][0], p0[1][1]],
            [x0, p0[2][0], p0[2][1]],

            [x1, p1[0][0], p1[0][1]],
            [x1, p1[1][0], p1[1][1]],
            [x1, p1[2][0], p1[2][1]]
        ],
        faces=[
            // caps (triangles)
            [0,1,2],
            [3,5,4],

            // side faces (each quad split into two triangles)
            [0,3,4], [0,4,1],
            [1,4,5], [1,5,2],
            [2,5,3], [2,3,0]
        ],
        convexity=10
    );
}

difference() {
    outer_body();

    // Two opposing tapered triangular through-openings (one from each end)
    tapered_tri_tunnel_half(-1);
    tapered_tri_tunnel_half( 1);
}

